// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this));
        vm.assume(actor != c.owner());
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // if the call succeeded, ownership must still be unchanged for non-owner callers
            assertTrue(c.owner() == address(0) || c.owner() == newOwner && actor == address(this), "non-owner changed ownership");
        } catch {
            // reference behavior: reverts, owner untouched
            assertTrue(c.owner() != newOwner || c.owner() == address(0), "owner mutated on revert");
        }
    }
}
